#!/usr/bin/env node
// Copies Ron's bloom master list (E:\Bloom\forage_national.json, edited in his separate Bloom workshop)
// into the app as api/_bloom/forageMaster.ts. The contents are copied exactly; only the wrapper changes,
// because the server functions load data as code rather than reading files.
//
// Usage: node scripts/sync-bloom-master.mjs [path-to-forage_national.json]
//        (default E:/Bloom/forage_national.json). Commit the regenerated file afterwards.

import { readFileSync, writeFileSync } from 'node:fs';

const src = process.argv[2] || 'E:/Bloom/forage_national.json';
const data = JSON.parse(readFileSync(src, 'utf8'));
if (!Array.isArray(data.plants) || data.gddBaseF !== 32) throw new Error(`${src}: expected { plants: [...], gddBaseF: 32 }`);
const names = data.plants.map((p) => p.common);
const dup = names.filter((n, i) => names.indexOf(n) !== i);
if (dup.length) throw new Error(`Duplicate plant names (the app uses the name as each plant's ID): ${dup.join(', ')}`);

const out = `// GENERATED by scripts/sync-bloom-master.mjs from ${src.replace(/\\/g, '/')} — do not edit here;
// edit the master list in the Bloom workshop and run the script again.
// ${data.plants.length} plants. Each plant's common name is its ID.
/* eslint-disable */
import type { ForageMaster } from './types.js';

export const FORAGE_MASTER: ForageMaster = ${JSON.stringify(data)};
`;
writeFileSync(new URL('../api/_bloom/forageMaster.ts', import.meta.url), out);
console.log(`Wrote api/_bloom/forageMaster.ts (${data.plants.length} plants).`);
